/**
 * THE METRICS THE LAYOUT USES
 * ---------------------------------------------------------------------------
 * A thin layer over `src/theme/font-metrics.ts`, which is GENERATED by
 * `scripts/generate-font-metrics.mjs` from the font files themselves.
 *
 * Two things live here:
 *
 *   · the numbers the layout engine measures in — the advance, the ascent,
 *     the descent, and the advance of the figures' face;
 *   · THE REPERTOIRE: the set of characters JetBrains Mono cannot draw.
 *
 * The repertoire is the interesting one. A character the font does not have
 * comes out as a BOX, and a page of boxes is worse than a page of plain
 * text. So `hasGlyph` is asked before a glyph is drawn, and the symbol table
 * supplies a fallback when the answer is no.
 */
import { FONT_METRICS } from "@/theme/font-metrics";

const math = FONT_METRICS.regular;
const nova = FONT_METRICS.nova;

export const MATH_METRICS = {
  /** The advance of every glyph in the body face, in em. */
  advance: math.advance,
  /** The advance of every glyph in the figures' face, in em. */
  novaAdvance: nova.advance,
  /** How far a glyph rises above the baseline, in em. */
  ascender: math.ascender,
  /** How far a glyph drops below the baseline, in em. */
  descenderDepth: -math.descender,
  /** The cap height, in em. */
  capHeight: math.capHeight,
  /** The x-height, in em. */
  xHeight: math.xHeight,
} as const;

/** Every character the app's fonts cannot draw. */
const MISSING: ReadonlySet<string> = new Set(
  [...math.missing, ...nova.missing].flatMap((group) => [...group]),
);

/**
 * Can the app draw this character?
 *
 * The answer is per CHARACTER rather than per symbol, because a symbol may
 * be several characters — `\iint` is two integral signs — and only the ones
 * the font is missing need a fallback.
 */
export function hasGlyph(text: string): boolean {
  for (const c of text) {
    if (!MISSING.has(c)) continue;
    return false;
  }
  return true;
}
